import warnings, itertools, math
from statsmodels.tsa.holtwinters import ExponentialSmoothing
from statsmodels.tsa.statespace.sarimax import SARIMAX
import statsmodels.api as sm
y=df['sales_units']

# ETS additive trend, additive seasonality, damped
models={}
for trend in [None,'add']:
    for damped in ([False, True] if trend else [False]):
        for seasonal in [None,'add','mul']:
            if seasonal and len(y)<24: continue
            try:
                fit=ExponentialSmoothing(y, trend=trend, damped_trend=damped, seasonal=seasonal, seasonal_periods=12, initialization_method='estimated').fit(optimized=True, use_brute=True)
                fc=fit.forecast(3)
                models[f"ETS_t{trend}_d{damped}_s{seasonal}"]=(fit.aic, fc.iloc[-1], fit)
            except Exception as e:
                pass
models

warnings.filterwarnings("ignore")
sarima_results=[]
# Use d=0/1, D=0/1, small
for order in itertools.product(range(0,3), [0,1], range(0,3)):
    for seas in itertools.product(range(0,2), [0,1], range(0,2)):
        if order==(0,0,0) and seas==(0,0,0): continue
        try:
            res=SARIMAX(y, order=order, seasonal_order=seas+(12,), trend='c' if order[1]==0 else 'n',
                        enforce_stationarity=False,enforce_invertibility=False).fit(disp=False, maxiter=200)
            if np.isfinite(res.aic):
                fc=res.get_forecast(3)
                sarima_results.append((res.aic, order, seas, fc.predicted_mean.iloc[-1], fc.conf_int(alpha=0.1).iloc[-1].tolist(), res))
        except Exception as e:
            pass
sorted(sarima_results, key=lambda x:x[0])[:10]

from sklearn.metrics import mean_absolute_error, mean_squared_error
def fit_forecast(method, train, h=3):
    if method=='snaive':
        return train.iloc[-12+h-1] if len(train)>=12 else train.iloc[-1]
    if method=='last_year_same_month':
        # for h date
        return train.iloc[-12+h-1]
    if method=='ets_add':
        return ExponentialSmoothing(train, trend=None, seasonal='add', seasonal_periods=12, initialization_method='estimated').fit(optimized=True).forecast(h).iloc[-1]
    if method=='ets_mul':
        return ExponentialSmoothing(train, trend=None, seasonal='mul', seasonal_periods=12, initialization_method='estimated').fit(optimized=True).forecast(h).iloc[-1]
    if method=='ols_log':
        tmp=pd.DataFrame({'y':train})
        tmp['t']=np.arange(len(tmp)); tmp['month']=tmp.index.month.astype(str)
        Xt=pd.get_dummies(tmp[['t','month']], columns=['month'], drop_first=True, dtype=float)
        Xt=sm.add_constant(Xt)
        res=sm.OLS(np.log(tmp['y']), Xt).fit()
        fut_idx=pd.date_range(train.index[-1]+pd.offsets.MonthBegin(1), periods=h, freq='MS')
        ff=pd.DataFrame(index=fut_idx); ff['t']=np.arange(len(tmp), len(tmp)+h); ff['month']=ff.index.month.astype(str)
        Xff=pd.get_dummies(ff[['t','month']], columns=['month'], drop_first=True, dtype=float)
        Xff=Xff.reindex(columns=Xt.columns.drop('const'), fill_value=0)
        Xff=sm.add_constant(Xff, has_constant='add')
        return float(np.exp(res.predict(Xff).iloc[-1]))
methods=['snaive','ets_add','ets_mul','ols_log']
errors={m:[] for m in methods}
preds_bt={m:[] for m in methods}
actuals=[]
dates=[]
for end in range(24, len(y)-3+1): # train length end, target end+2
    train=y.iloc[:end]
    target=y.iloc[end+2]
    actuals.append(target); dates.append(y.index[end+2])
    for m in methods:
        try:
            p=fit_forecast(m, train, 3)
            errors[m].append(p-target)
            preds_bt[m].append(p)
        except Exception as e:
            errors[m].append(np.nan)
for m in methods:
    e=np.array(errors[m], dtype=float)
    print(m, "n", np.sum(~np.isnan(e)), "MAE", np.nanmean(abs(e)), "RMSE", np.sqrt(np.nanmean(e**2)), "bias", np.nanmean(e), "MAPE", np.nanmean(abs(e/actuals)))
pd.DataFrame({'date':dates,'actual':actuals, **{m:preds_bt[m] for m in methods}, **{m+'_err':errors[m] for m in methods}}).round(0)
